const money = (n: number) => n.toLocaleString("de-DE", { style: "currency", currency: "EUR" });
type AccountUrgency="guest"|"overdue"|"member";
const accountOpenSince=(account:ControlData["accounts"][number],entries:NonNullable<ControlData["accountEntries"]>)=>{let reverseBalance=0;const current=Number(account.balance);for(const entry of entries.filter(item=>item.memberId===account.memberId).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))){reverseBalance+=Number(entry.amount);if(reverseBalance>=current-.005)return entry.createdAt}return null};
const memberDueDate=(bookingDate:string)=>{const booking=new Date(bookingDate);return new Date(booking.getFullYear(),booking.getMonth()+1,10,23,59,59,999)};
const accountUrgency=(account:ControlData["accounts"][number],entries:NonNullable<ControlData["accountEntries"]>):AccountUrgency=>{if(account.accountType==="guest")return "guest";const since=accountOpenSince(account,entries);return since&&Date.now()>memberDueDate(since).getTime()?"overdue":"member"};
const accountStatusLabel=(account:ControlData["accounts"][number],entries:NonNullable<ControlData["accountEntries"]>)=>{const urgency=accountUrgency(account,entries);if(urgency==="guest")return "⚠ Nichtmitglied · bitte zeitnah abrechnen";const since=accountOpenSince(account,entries);if(!since)return "Mitglied · Abrechnung zum Monatsende · zahlbar bis 10. des Folgemonats";const due=memberDueDate(since),date=due.toLocaleDateString("de-DE",{day:"2-digit",month:"2-digit",year:"numeric"});return urgency==="overdue"?`⚠ Mitglied · seit ${date} überfällig`:`Mitglied · Abrechnung zum Monatsende · zahlbar bis ${date}`};
const cleanMoneyInput=(value:string)=>{const parts=value.replace(".",",").replace(/[^\d,]/g,"").split(",");return parts.length>1?`${parts[0]},${parts.slice(1).join("").slice(0,2)}`:parts[0]};
const includedDescription=(product:Product,all:Product[])=>(product.includedItems||[]).map(item=>`${item.quantity}× ${all.find(candidate=>candidate.id===item.productId)?.name||"Artikel"}`).join(" + ");
const includedValue=(product:Product,all:Product[])=>(product.includedItems||[]).reduce((sum,item)=>sum+(all.find(candidate=>candidate.id===item.productId)?.price||0)*item.quantity,0);
const MembersContext=createContext<Member[]>(members);
const safeArray=<T,>(value:string|null):T[]=>{try{const parsed=JSON.parse(value||"[]");return Array.isArray(parsed)?parsed:[]}catch{return []}};

